package org.eclipse.kura.linux.watchdog;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.io.File;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

import org.eclipse.kura.KuraErrorCode;
import org.eclipse.kura.KuraException;
import org.eclipse.kura.core.testutil.TestUtil;
import org.eclipse.kura.watchdog.CriticalComponent;
import org.eclipse.kura.watchdog.WatchdogState;
import org.junit.After;
import org.junit.Test;

public class CriticalComponentRebootTest {

    private static final String WATCHDOG_DEVICE = "target/criticalComponentRebootTestDevice";
    private static final String REBOOT_CAUSE_FILE = "target/criticalComponentRebootCause";
    private static final int PING_INTERVAL_MS = 20;
    private static final long SHORT_GRACE_PERIOD_MS = 200;
    private static final long LONG_GRACE_PERIOD_MS = 10000;
    private static final long OBSERVATION_TIME_MS = 200;

    private long gracePeriodMs = LONG_GRACE_PERIOD_MS;
    private boolean rebootFails;
    private RebootTestDevice device;
    private RebootWatchdogServiceImpl svc;
    private int keepAlivesBeforeObservation;

    @Test
    public void watchdogIsRefreshedDuringGracePeriodAfterRebootIsRequested() throws Exception {
        givenWatchdogServiceActivated();

        whenCriticalComponentTimesOut();
        whenRebootIsRequested();
        whenWatchdogIsObserved();

        thenStateIs(WatchdogState.REBOOT_REQUESTED);
        thenWatchdogIsRefreshed();
    }

    @Test
    public void watchdogIsNotRefreshedAfterGracePeriodWhenRebootIsRequested() throws Exception {
        givenGracePeriod(SHORT_GRACE_PERIOD_MS);
        givenWatchdogServiceActivated();

        whenCriticalComponentTimesOut();
        whenRebootIsRequested();
        whenGracePeriodElapses();
        whenWatchdogIsObserved();

        thenStateIs(WatchdogState.REBOOT_REQUESTED);
        thenWatchdogIsNotRefreshed();
        thenDeviceIsOpenAndArmed();
    }

    @Test
    public void watchdogIsNotRefreshedWhenRebootFails() throws Exception {
        givenFailingReboot();
        givenWatchdogServiceActivated();

        whenCriticalComponentTimesOut();
        whenRebootIsRequested();
        whenWatchdogIsObserved();

        thenStateIs(WatchdogState.REBOOT_REQUESTED);
        thenWatchdogIsNotRefreshed();
        thenDeviceIsOpenAndArmed();
        thenRebootIsRequestedOnlyOnce();
    }

    @After
    public void cleanup() {
        if (this.svc != null) {
            this.svc.deactivate();
        }
        new File(REBOOT_CAUSE_FILE).delete();
    }

    private void givenGracePeriod(long newGracePeriodMs) {
        this.gracePeriodMs = newGracePeriodMs;
    }

    private void givenFailingReboot() {
        this.rebootFails = true;
    }

    private void givenWatchdogServiceActivated() {
        final Map<String, Object> properties = new HashMap<>();
        properties.put("enabled", true);
        properties.put("watchdogDevice", WATCHDOG_DEVICE);
        properties.put("watchdogMode", "direct");
        properties.put("pingInterval", PING_INTERVAL_MS);
        properties.put("rebootCauseFilePath", REBOOT_CAUSE_FILE);
        this.svc = new RebootWatchdogServiceImpl();
        this.svc.activate(properties);
    }

    private void whenCriticalComponentTimesOut() {
        this.svc.registerCriticalComponent(new CriticalComponent() {

            @Override
            public String getCriticalComponentName() {
                return "testComponent";
            }

            @Override
            public int getCriticalComponentTimeout() {
                return 0;
            }
        });
    }

    private void whenRebootIsRequested() throws Exception {
        assertTrue(this.svc.waitForRebootRequest(TimeUnit.SECONDS.toMillis(10)));
        awaitPendingTasks();
    }

    private void whenGracePeriodElapses() throws Exception {
        Thread.sleep(this.gracePeriodMs * 2);
        awaitPendingTasks();
    }

    private void whenWatchdogIsObserved() throws Exception {
        this.keepAlivesBeforeObservation = this.device.getKeepAlives();
        Thread.sleep(OBSERVATION_TIME_MS);
        awaitPendingTasks();
    }

    private void thenStateIs(WatchdogState expectedState) {
        assertEquals(expectedState, this.svc.getWatchdogStatus().getState());
    }

    private void thenWatchdogIsRefreshed() {
        assertTrue(this.device.getKeepAlives() > this.keepAlivesBeforeObservation);
    }

    private void thenWatchdogIsNotRefreshed() {
        assertEquals(this.keepAlivesBeforeObservation, this.device.getKeepAlives());
    }

    private void thenDeviceIsOpenAndArmed() {
        assertTrue(this.svc.getWatchdogStatus().isDeviceOpen());
        assertFalse(this.device.isClosed());
        assertFalse(this.device.isDisarmed());
    }

    private void thenRebootIsRequestedOnlyOnce() {
        assertEquals(1, this.svc.getRebootRequests());
    }

    private void awaitPendingTasks() throws Exception {
        ScheduledExecutorService pollExecutor = (ScheduledExecutorService) TestUtil.getFieldValue(this.svc,
                "pollExecutor");
        pollExecutor.submit(() -> {
        }).get(10, TimeUnit.SECONDS);
    }

    private static class RebootTestDevice implements WatchdogDevice {

        private int keepAlives;
        private boolean disarmed;
        private boolean closed;

        @Override
        public synchronized void keepAlive() {
            this.keepAlives++;
        }

        @Override
        public int getTimeout() {
            return 0;
        }

        @Override
        public synchronized void disarm() {
            this.disarmed = true;
        }

        @Override
        public synchronized void close() {
            this.closed = true;
        }

        synchronized int getKeepAlives() {
            return this.keepAlives;
        }

        synchronized boolean isDisarmed() {
            return this.disarmed;
        }

        synchronized boolean isClosed() {
            return this.closed;
        }
    }

    private class RebootWatchdogServiceImpl extends HookedWatchdogServiceImpl {

        private int rebootRequests;

        @Override
        protected WatchdogDevice createWatchdogDevice(String watchdogDevice) {
            CriticalComponentRebootTest.this.device = new RebootTestDevice();
            return CriticalComponentRebootTest.this.device;
        }

        @Override
        protected boolean isWatchdogDeviceAvailable(String watchdogDevice) {
            return true;
        }

        @Override
        protected void stopWatchdogd() {
            // do not run system commands in tests
        }

        @Override
        protected long getGracePeriod() {
            return CriticalComponentRebootTest.this.gracePeriodMs;
        }

        @Override
        protected synchronized void rebootSystem() throws KuraException {
            this.rebootRequests++;
            notifyAll();
            if (CriticalComponentRebootTest.this.rebootFails) {
                throw new KuraException(KuraErrorCode.OS_COMMAND_ERROR, "reboot", 1);
            }
        }

        synchronized int getRebootRequests() {
            return this.rebootRequests;
        }

        synchronized boolean waitForRebootRequest(long timeoutMs) throws InterruptedException {
            final long deadline = System.currentTimeMillis() + timeoutMs;
            long remaining = timeoutMs;
            while (this.rebootRequests == 0 && remaining > 0) {
                wait(remaining);
                remaining = deadline - System.currentTimeMillis();
            }
            return this.rebootRequests > 0;
        }
    }
}
